{"packet_id":"D041-01","doc_id":"D041","jurisdiction":"Los Angeles, CA","category":"rent_increase_limits","lifecycle":"enacted","title":"Los Angeles RSO allowable rent increase","requirement":"The RSO allows rent increases only once every 12 months at the annual allowable percentage; as of February 2, 2026 utility and dependent percentage increases are barred. Landlords may add specified surcharges (registration, code enforcement, smoke detector) and 10% for an additional tenant.","key_value":"once every 12 months at allowable %; 10% additional-tenant increase within 60 days","coverage_conditions":"Rental units first built on or before October 1, 1978 in the City of Los Angeles, including replacement units and listed property types such as apartments, duplexes, ADUs, JADUs and mobile homes.","applicability":{"built_on_or_before":"1978-10-01","built_after":null,"date_basis":"construction_date","min_units":null,"max_units":null,"owner_dependent":false,"other":"Includes replacement units under LAMC Section 151.28"},"exemptions":"Rent amount not regulated for condominium or townhome tenancies that commenced after December 31, 1995; luxury exemption where the monthly rent charged on or before May 31, 1978 qualifies.","penalty":null,"effective_date":"2026-02-02","citation":"Los Angeles Rent Stabilization Ordinance (L.A.M.C. §151.00 et seq.)","quoted_span":"Effective February 2, 2026, an additonal 10% increase for an additional dependent added to the tenancy is no longer permitted. However, a 10% for an additional tenant is allowed (not a dependent) if moves into a rental unit: Landlords can increase the rent within 60 days of learning about the additional tenant.","interaction":null,"confidence":0.75,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D041-01","doc_id":"D041","jurisdiction":"Los Angeles, CA","category":"just_cause_eviction","lifecycle":"enacted","title":"Los Angeles RSO just cause eviction grounds and relocation","requirement":"RSO landlords may terminate a tenancy only for the listed at-fault or no-fault reasons; all termination notices must be filed with LAHD within three business days of service, and no-fault evictions require relocation assistance plus 30-, 60- or 120-day notice.","key_value":"3 business days to file notice; 30/60/120-day notices","coverage_conditions":"All rental units subject to the City’s Rent Stabilization Ordinance, i.e. properties first built on or before October 1, 1978.","applicability":{"built_on_or_before":"1978-10-01","built_after":null,"date_basis":"construction_date","min_units":null,"max_units":null,"owner_dependent":false,"other":null},"exemptions":null,"penalty":null,"effective_date":null,"citation":"Los Angeles Rent Stabilization Ordinance (L.A.M.C. §151.00 et seq.)","quoted_span":"All notices to terminate a tenancy for all rental units subject to City’s Rent Stabilization Ordinance (RSO) must be filed with the Los Angeles Housing Department (LAHD) within three (3) business days of service on the tenant per Los Angeles Municipal Code 151.09.C.9 & 165.05.B.5.","interaction":"Non-RSO rental properties are instead covered by the City’s Just Cause Ordinance.","confidence":0.75,"conflict_flag":false,"conflict_note":null}
